+    private static async Task InstallStatusChangeAuditAsync(
+        WorkItemsApiFactory factory,
+        CancellationToken cancellationToken)
+    {
+        await using var scope = factory.Services.CreateAsyncScope();
+        var database = scope.ServiceProvider.GetRequiredService<WorkItemsDbContext>();
+        await database.Database.ExecuteSqlRawAsync(
+            """
+            CREATE TABLE "StatusChangeAudit" (
+                "WorkItemId" TEXT NOT NULL
+            );
+            """,
+            cancellationToken);
+        await database.Database.ExecuteSqlRawAsync(
+            """
+            CREATE TRIGGER "TrackWorkItemStatusChanges"
+            AFTER UPDATE OF "Status" ON "WorkItems"
+            FOR EACH ROW
+            WHEN OLD."Status" <> NEW."Status"
+            BEGIN
+                INSERT INTO "StatusChangeAudit" ("WorkItemId") VALUES (NEW."Id");
+            END;
+            """,
+            cancellationToken);
+    }
+
+    private static async Task<int> CountStatusChangesAsync(
+        WorkItemsApiFactory factory,
+        CancellationToken cancellationToken)
+    {
+        await using var scope = factory.Services.CreateAsyncScope();
+        var database = scope.ServiceProvider.GetRequiredService<WorkItemsDbContext>();
+        return await database.Database
+            .SqlQueryRaw<int>("SELECT COUNT(*) AS \"Value\" FROM \"StatusChangeAudit\"")
+            .SingleAsync(cancellationToken);
+    }
+
