diff --git a/tests/WorkItems.Api.Tests/ProcessOverdueAcceptanceTests.cs b/tests/WorkItems.Api.Tests/ProcessOverdueAcceptanceTests.cs
new file mode 100644
index 0000000..0f89599
--- /dev/null
+++ b/tests/WorkItems.Api.Tests/ProcessOverdueAcceptanceTests.cs
@@ -0,0 +1,191 @@
+using System.Net;
+using System.Net.Http.Json;
+using System.Text.Json;
+using Microsoft.EntityFrameworkCore;
+using Microsoft.Extensions.DependencyInjection;
+using WorkItems.Api.Data;
+using WorkItems.Api.Models;
+using Xunit;
+
+namespace WorkItems.Api.Tests;
+
+public sealed class ProcessOverdueAcceptanceTests
+{
+    [Fact]
+    public async Task ProcessOverdue_WhenItemIsDueExactlyNow_ProcessesItThroughTheHttpContract()
+    {
+        var cancellationToken = TestContext.Current.CancellationToken;
+        using var factory = new WorkItemsApiFactory();
+        using var client = factory.CreateClient();
+        var workItem = CreateOpenWorkItem("剛好到期", factory.UtcNow);
+        await SeedAsync(factory, workItem, cancellationToken);
+
+        using var response = await client.PostAsync(
+            "/api/work-items/process-overdue",
+            null,
+            cancellationToken);
+        var responseBody = await response.Content.ReadAsStringAsync(cancellationToken);
+        using var json = JsonDocument.Parse(responseBody);
+        var summary = JsonSerializer.Deserialize<ProcessOverdueHttpContract>(
+            responseBody,
+            JsonSerializerOptions.Web);
+
+        Assert.Equal(HttpStatusCode.OK, response.StatusCode);
+        Assert.Equal(
+            [
+                "failedNotificationWorkItemIds",
+                "notificationAttemptCount",
+                "notificationFailureCount",
+                "processedCount"
+            ],
+            json.RootElement.EnumerateObject().Select(property => property.Name).Order().ToArray());
+        AssertSummary(summary, processedCount: 1, attemptCount: 1, failureCount: 0);
+
+        var databaseSnapshot = await ReadDatabaseSnapshotAsync(factory, cancellationToken);
+        Assert.Equal(1, databaseSnapshot.RowCount);
+        Assert.Equal("Overdue", databaseSnapshot.StatusById[workItem.Id]);
+        Assert.Equal([workItem.Id], factory.Notifications.AttemptedWorkItemIds);
+    }
+
+    [Fact]
+    public async Task ProcessOverdue_WhenNotificationReportsFailure_StillSavesAfterTheAttempt()
+    {
+        var cancellationToken = TestContext.Current.CancellationToken;
+        WorkItemsApiFactory? factoryForNotification = null;
+        string? persistedStatusDuringNotification = null;
+
+        using var factory = new WorkItemsApiFactory(
+            notificationHandler: async (workItem, token) =>
+            {
+                await using var scope = factoryForNotification!.Services.CreateAsyncScope();
+                var database = scope.ServiceProvider.GetRequiredService<WorkItemsDbContext>();
+                persistedStatusDuringNotification = await database.WorkItems
+                    .AsNoTracking()
+                    .Where(candidate => candidate.Id == workItem.Id)
+                    .Select(candidate => candidate.Status)
+                    .SingleAsync(token);
+                return false;
+            });
+        factoryForNotification = factory;
+        using var client = factory.CreateClient();
+        var workItem = CreateOpenWorkItem("通知失敗仍須儲存", factory.UtcNow.AddMinutes(-1));
+        await SeedAsync(factory, workItem, cancellationToken);
+
+        using var response = await client.PostAsync(
+            "/api/work-items/process-overdue",
+            null,
+            cancellationToken);
+        var summary = await response.Content.ReadFromJsonAsync<ProcessOverdueHttpContract>(
+            cancellationToken: cancellationToken);
+
+        Assert.Equal(HttpStatusCode.OK, response.StatusCode);
+        AssertSummary(
+            summary,
+            processedCount: 1,
+            attemptCount: 1,
+            failureCount: 1,
+            workItem.Id);
+        Assert.Equal("Open", persistedStatusDuringNotification);
+        Assert.Equal([workItem.Id], factory.Notifications.AttemptedWorkItemIds);
+
+        var databaseSnapshot = await ReadDatabaseSnapshotAsync(factory, cancellationToken);
+        Assert.Equal(1, databaseSnapshot.RowCount);
+        Assert.Equal("Overdue", databaseSnapshot.StatusById[workItem.Id]);
+    }
+
+    [Fact]
+    public async Task ProcessOverdue_WhenRunAgain_DoesNotRepeatTheStateChangeOrCreateAnotherRow()
+    {
+        var cancellationToken = TestContext.Current.CancellationToken;
+        using var factory = new WorkItemsApiFactory();
+        using var client = factory.CreateClient();
+        var workItem = CreateOpenWorkItem("重跑驗收", factory.UtcNow.AddMinutes(-1));
+        await SeedAsync(factory, workItem, cancellationToken);
+
+        using var firstResponse = await client.PostAsync(
+            "/api/work-items/process-overdue",
+            null,
+            cancellationToken);
+        var firstSummary = await firstResponse.Content.ReadFromJsonAsync<ProcessOverdueHttpContract>(
+            cancellationToken: cancellationToken);
+        var snapshotAfterFirstRun = await ReadDatabaseSnapshotAsync(factory, cancellationToken);
+
+        using var secondResponse = await client.PostAsync(
+            "/api/work-items/process-overdue",
+            null,
+            cancellationToken);
+        var secondSummary = await secondResponse.Content.ReadFromJsonAsync<ProcessOverdueHttpContract>(
+            cancellationToken: cancellationToken);
+        var snapshotAfterSecondRun = await ReadDatabaseSnapshotAsync(factory, cancellationToken);
+
+        Assert.Equal(HttpStatusCode.OK, firstResponse.StatusCode);
+        Assert.Equal(HttpStatusCode.OK, secondResponse.StatusCode);
+        AssertSummary(firstSummary, processedCount: 1, attemptCount: 1, failureCount: 0);
+        AssertSummary(secondSummary, processedCount: 0, attemptCount: 1, failureCount: 0);
+
+        Assert.Equal(1, snapshotAfterFirstRun.RowCount);
+        Assert.Equal("Overdue", snapshotAfterFirstRun.StatusById[workItem.Id]);
+        Assert.Equal(1, snapshotAfterSecondRun.RowCount);
+        Assert.Equal("Overdue", snapshotAfterSecondRun.StatusById[workItem.Id]);
+
+        // 系列基準保留重跑通知；資料狀態不重複轉換，但每次執行仍各嘗試一次通知。
+        Assert.Equal([workItem.Id, workItem.Id], factory.Notifications.AttemptedWorkItemIds);
+    }
+
+    private static WorkItem CreateOpenWorkItem(string title, DateTimeOffset dueAtUtc) =>
+        new()
+        {
+            Id = Guid.NewGuid(),
+            Title = title,
+            Priority = "Normal",
+            DueAtUtc = dueAtUtc,
+            CreatedAtUtc = dueAtUtc.AddDays(-1)
+        };
+
+    private static async Task SeedAsync(
+        WorkItemsApiFactory factory,
+        WorkItem workItem,
+        CancellationToken cancellationToken)
+    {
+        await using var scope = factory.Services.CreateAsyncScope();
+        var database = scope.ServiceProvider.GetRequiredService<WorkItemsDbContext>();
+        database.WorkItems.Add(workItem);
+        await database.SaveChangesAsync(cancellationToken);
+    }
+
+    private static async Task<DatabaseSnapshot> ReadDatabaseSnapshotAsync(
+        WorkItemsApiFactory factory,
+        CancellationToken cancellationToken)
+    {
+        await using var scope = factory.Services.CreateAsyncScope();
+        var database = scope.ServiceProvider.GetRequiredService<WorkItemsDbContext>();
+        var statusById = await database.WorkItems
+            .AsNoTracking()
+            .ToDictionaryAsync(workItem => workItem.Id, workItem => workItem.Status, cancellationToken);
+        return new DatabaseSnapshot(statusById.Count, statusById);
+    }
+
+    private static void AssertSummary(
+        ProcessOverdueHttpContract? actual,
+        int processedCount,
+        int attemptCount,
+        int failureCount,
+        params Guid[] failedWorkItemIds)
+    {
+        var summary = Assert.IsType<ProcessOverdueHttpContract>(actual);
+        Assert.Equal(processedCount, summary.ProcessedCount);
+        Assert.Equal(attemptCount, summary.NotificationAttemptCount);
+        Assert.Equal(failureCount, summary.NotificationFailureCount);
+        Assert.Equal(failedWorkItemIds, summary.FailedNotificationWorkItemIds);
+    }
+
+    private sealed record ProcessOverdueHttpContract(
+        int ProcessedCount,
+        int NotificationAttemptCount,
+        int NotificationFailureCount,
+        Guid[] FailedNotificationWorkItemIds);
+
+    private sealed record DatabaseSnapshot(
+        int RowCount,
+        IReadOnlyDictionary<Guid, string> StatusById);
+}

