+using System.Net;
+using System.Text.Json;
+using Microsoft.EntityFrameworkCore;
+using Microsoft.Extensions.DependencyInjection;
+using WorkItems.Api.Data;
+using WorkItems.Api.Models;
+using Xunit;
+
+namespace WorkItems.Api.Tests;
+
+public sealed class ProcessOverdueAcceptanceTests
+{
+    [Fact]
+    public async Task ProcessOverdue_WhenDueTimeEqualsCurrentTime_ProcessesTheBoundaryItem()
+    {
+        var cancellationToken = TestContext.Current.CancellationToken;
+        using var factory = new WorkItemsApiFactory();
+        using var client = factory.CreateClient();
+        var boundaryItem = CreateOpenWorkItem("剛好到期", factory.UtcNow);
+        var futureItem = CreateOpenWorkItem("尚差一毫秒到期", factory.UtcNow.AddMilliseconds(1));
+        await SeedAsync(factory, cancellationToken, boundaryItem, futureItem);
+
+        using var response = await client.PostAsync(
+            "/api/work-items/process-overdue",
+            null,
+            cancellationToken);
+        var responseBody = await response.Content.ReadAsStringAsync(cancellationToken);
+        using var responseJson = JsonDocument.Parse(responseBody);
+        var summary = JsonSerializer.Deserialize<ProcessOverdueContract>(
+            responseBody,
+            JsonSerializerOptions.Web);
+
+        Assert.Equal(HttpStatusCode.OK, response.StatusCode);
+        Assert.Equal(
+            [
+                "failedNotificationWorkItemIds",
+                "notificationAttemptCount",
+                "notificationFailureCount",
+                "processedCount"
+            ],
+            responseJson.RootElement
+                .EnumerateObject()
+                .Select(property => property.Name)
+                .Order()
+                .ToArray());
+        Assert.NotNull(summary);
+        Assert.Equal(1, summary.ProcessedCount);
+        Assert.Equal(1, summary.NotificationAttemptCount);
+        Assert.Equal(0, summary.NotificationFailureCount);
+        Assert.Empty(summary.FailedNotificationWorkItemIds);
+
+        Assert.Equal([boundaryItem.Id], factory.Notifications.AttemptedWorkItemIds);
+        var persistedStatuses = await ReadPersistedStatusesAsync(factory, cancellationToken);
+        Assert.Equal("Overdue", persistedStatuses[boundaryItem.Id]);
+        Assert.Equal("Open", persistedStatuses[futureItem.Id]);
+    }
+
+    [Fact]
+    public async Task ProcessOverdue_WhenNotificationReportsFailure_PersistsAfterTheAttempt()
+    {
+        var cancellationToken = TestContext.Current.CancellationToken;
+        WorkItemsApiFactory? callbackFactory = null;
+        string? persistedStatusDuringNotification = null;
+
+        using var factory = new WorkItemsApiFactory(
+            notificationHandler: async (workItem, token) =>
+            {
+                await using var scope = callbackFactory!.Services.CreateAsyncScope();
+                var database = scope.ServiceProvider.GetRequiredService<WorkItemsDbContext>();
+                persistedStatusDuringNotification = await database.WorkItems
+                    .AsNoTracking()
+                    .Where(candidate => candidate.Id == workItem.Id)
+                    .Select(candidate => candidate.Status)
+                    .SingleAsync(token);
+                return false;
+            });
+        callbackFactory = factory;
+        using var client = factory.CreateClient();
+        var workItem = CreateOpenWorkItem("通知失敗仍須儲存", factory.UtcNow.AddMinutes(-1));
+        await SeedAsync(factory, cancellationToken, workItem);
+
+        using var response = await client.PostAsync(
+            "/api/work-items/process-overdue",
+            null,
+            cancellationToken);
+        var responseBody = await response.Content.ReadAsStringAsync(cancellationToken);
+        var summary = JsonSerializer.Deserialize<ProcessOverdueContract>(
+            responseBody,
+            JsonSerializerOptions.Web);
+
+        Assert.Equal(HttpStatusCode.OK, response.StatusCode);
+        Assert.NotNull(summary);
+        Assert.Equal(1, summary.ProcessedCount);
+        Assert.Equal(1, summary.NotificationAttemptCount);
+        Assert.Equal(1, summary.NotificationFailureCount);
+        Assert.Equal([workItem.Id], summary.FailedNotificationWorkItemIds);
+
+        Assert.Equal("Open", persistedStatusDuringNotification);
+        Assert.Equal([workItem.Id], factory.Notifications.AttemptedWorkItemIds);
+        var persistedStatuses = await ReadPersistedStatusesAsync(factory, cancellationToken);
+        Assert.Equal("Overdue", persistedStatuses[workItem.Id]);
+    }
+
+    [Fact]
+    public async Task ProcessOverdue_WhenRunAgain_DoesNotRepeatThePersistedStateTransition()
+    {
+        var cancellationToken = TestContext.Current.CancellationToken;
+        using var factory = new WorkItemsApiFactory();
+        using var client = factory.CreateClient();
+        var workItem = CreateOpenWorkItem("重跑不重複轉換", factory.UtcNow.AddMinutes(-1));
+        await SeedAsync(factory, cancellationToken, workItem);
+
+        using var firstResponse = await client.PostAsync(
+            "/api/work-items/process-overdue",
+            null,
+            cancellationToken);
+        var firstResponseBody = await firstResponse.Content.ReadAsStringAsync(cancellationToken);
+        var firstSummary = JsonSerializer.Deserialize<ProcessOverdueContract>(
+            firstResponseBody,
+            JsonSerializerOptions.Web);
+
+        using var secondResponse = await client.PostAsync(
+            "/api/work-items/process-overdue",
+            null,
+            cancellationToken);
+        var secondResponseBody = await secondResponse.Content.ReadAsStringAsync(cancellationToken);
+        var secondSummary = JsonSerializer.Deserialize<ProcessOverdueContract>(
+            secondResponseBody,
+            JsonSerializerOptions.Web);
+
+        Assert.Equal(HttpStatusCode.OK, firstResponse.StatusCode);
+        Assert.Equal(HttpStatusCode.OK, secondResponse.StatusCode);
+        Assert.NotNull(firstSummary);
+        Assert.NotNull(secondSummary);
+        Assert.Equal(1, firstSummary.ProcessedCount);
+        Assert.Equal(0, secondSummary.ProcessedCount);
+        Assert.Equal(1, firstSummary.NotificationAttemptCount);
+        Assert.Equal(1, secondSummary.NotificationAttemptCount);
+        Assert.Equal(0, firstSummary.NotificationFailureCount);
+        Assert.Equal(0, secondSummary.NotificationFailureCount);
+
+        Assert.Equal(
+            [workItem.Id, workItem.Id],
+            factory.Notifications.AttemptedWorkItemIds);
+        var persistedItems = await ReadPersistedItemsAsync(factory, cancellationToken);
+        var persistedItem = Assert.Single(persistedItems);
+        Assert.Equal(workItem.Id, persistedItem.Id);
+        Assert.Equal("Overdue", persistedItem.Status);
+        Assert.Equal(workItem.DueAtUtc, persistedItem.DueAtUtc);
+        Assert.Equal(workItem.CreatedAtUtc, persistedItem.CreatedAtUtc);
+    }
+
+    private static WorkItem CreateOpenWorkItem(string title, DateTimeOffset dueAtUtc) =>
+        new()
+        {
+            Id = Guid.NewGuid(),
+            Title = title,
+            Priority = "Normal",
+            DueAtUtc = dueAtUtc,
+            CreatedAtUtc = dueAtUtc.AddDays(-1)
+        };
+
+    private static async Task SeedAsync(
+        WorkItemsApiFactory factory,
+        CancellationToken cancellationToken,
+        params WorkItem[] workItems)
+    {
+        await using var scope = factory.Services.CreateAsyncScope();
+        var database = scope.ServiceProvider.GetRequiredService<WorkItemsDbContext>();
+        database.WorkItems.AddRange(workItems);
+        await database.SaveChangesAsync(cancellationToken);
+    }
+
+    private static async Task<Dictionary<Guid, string>> ReadPersistedStatusesAsync(
+        WorkItemsApiFactory factory,
+        CancellationToken cancellationToken)
+    {
+        await using var scope = factory.Services.CreateAsyncScope();
+        var database = scope.ServiceProvider.GetRequiredService<WorkItemsDbContext>();
+        return await database.WorkItems
+            .AsNoTracking()
+            .ToDictionaryAsync(item => item.Id, item => item.Status, cancellationToken);
+    }
+
+    private static async Task<WorkItem[]> ReadPersistedItemsAsync(
+        WorkItemsApiFactory factory,
+        CancellationToken cancellationToken)
+    {
+        await using var scope = factory.Services.CreateAsyncScope();
+        var database = scope.ServiceProvider.GetRequiredService<WorkItemsDbContext>();
+        return await database.WorkItems
+            .AsNoTracking()
+            .ToArrayAsync(cancellationToken);
+    }
+
+    private sealed record ProcessOverdueContract(
+        int ProcessedCount,
+        int NotificationAttemptCount,
+        int NotificationFailureCount,
+        Guid[] FailedNotificationWorkItemIds);
+}

