diff --git a/src/WorkItems.Api/OverdueProcessingCoordinator.cs b/src/WorkItems.Api/OverdueProcessingCoordinator.cs
new file mode 100644
index 0000000..f305d70
--- /dev/null
+++ b/src/WorkItems.Api/OverdueProcessingCoordinator.cs
@@ -0,0 +1,80 @@
+using WorkItems.Api.Contracts;
+
+namespace WorkItems.Api;
+
+/// <summary>
+/// 協調同一個 Host 內重疊的逾期處理，讓呼叫端共用進行中的執行結果。
+/// </summary>
+public sealed class OverdueProcessingCoordinator
+{
+    private readonly object synchronizationRoot = new();
+    private Task<ProcessOverdueResponse>? activeExecution;
+
+    /// <summary>
+    /// 執行逾期處理；已有執行進行中時，等待並回傳相同結果。
+    /// </summary>
+    /// <param name="operation">實際逾期處理作業。</param>
+    /// <param name="cancellationToken">目前呼叫端的取消權杖。</param>
+    /// <returns>本次共用執行的處理摘要。</returns>
+    public Task<ProcessOverdueResponse> RunAsync(
+        Func<CancellationToken, Task<ProcessOverdueResponse>> operation,
+        CancellationToken cancellationToken)
+    {
+        TaskCompletionSource<ProcessOverdueResponse>? executionSource = null;
+        Task<ProcessOverdueResponse> execution;
+
+        lock (synchronizationRoot)
+        {
+            if (activeExecution is null)
+            {
+                executionSource = new TaskCompletionSource<ProcessOverdueResponse>(
+                    TaskCreationOptions.RunContinuationsAsynchronously);
+                activeExecution = executionSource.Task;
+            }
+
+            execution = activeExecution;
+        }
+
+        if (executionSource is not null)
+        {
+            _ = CompleteExecutionAsync(operation, cancellationToken, executionSource);
+            return execution;
+        }
+
+        return execution.WaitAsync(cancellationToken);
+    }
+
+    private async Task CompleteExecutionAsync(
+        Func<CancellationToken, Task<ProcessOverdueResponse>> operation,
+        CancellationToken cancellationToken,
+        TaskCompletionSource<ProcessOverdueResponse> executionSource)
+    {
+        try
+        {
+            var result = await operation(cancellationToken);
+            ClearActiveExecution(executionSource.Task);
+            executionSource.TrySetResult(result);
+        }
+        catch (OperationCanceledException exception)
+        {
+            ClearActiveExecution(executionSource.Task);
+            executionSource.TrySetException(exception);
+        }
+        catch (Exception exception)
+        {
+            ClearActiveExecution(executionSource.Task);
+            executionSource.TrySetException(exception);
+        }
+    }
+
+    private void ClearActiveExecution(Task<ProcessOverdueResponse> completedExecution)
+    {
+        lock (synchronizationRoot)
+        {
+            if (ReferenceEquals(activeExecution, completedExecution))
+            {
+                activeExecution = null;
+            }
+        }
+    }
+}

