diff --git a/src/WorkItems.Api/OverdueProcessingConcurrencyCoordinator.cs b/src/WorkItems.Api/OverdueProcessingConcurrencyCoordinator.cs
new file mode 100644
index 0000000..6863cfa
--- /dev/null
+++ b/src/WorkItems.Api/OverdueProcessingConcurrencyCoordinator.cs
@@ -0,0 +1,168 @@
+using System.Collections.Concurrent;
+
+namespace WorkItems.Api;
+
+/// <summary>
+/// 協調同一應用程式執行個體內彼此重疊的逾期處理，避免同一工作項目重複通知。
+/// </summary>
+public interface IOverdueProcessingConcurrencyCoordinator
+{
+    /// <summary>
+    /// 開始一輪逾期處理。
+    /// </summary>
+    /// <returns>用來協調本輪通知嘗試的 Session。</returns>
+    IOverdueProcessingSession BeginSession();
+}
+
+/// <summary>
+/// 協調單輪逾期處理中的通知嘗試。
+/// </summary>
+public interface IOverdueProcessingSession : IDisposable
+{
+    /// <summary>
+    /// 進入指定工作項目的通知嘗試區段。
+    /// </summary>
+    /// <param name="workItemId">工作項目識別碼。</param>
+    /// <param name="cancellationToken">取消權杖。</param>
+    /// <returns>指出本輪是否應呼叫通知 Gateway 的 Lease。</returns>
+    Task<NotificationAttemptLease> EnterNotificationAttemptAsync(
+        Guid workItemId,
+        CancellationToken cancellationToken);
+}
+
+/// <summary>
+/// 表示指定工作項目的通知嘗試權限。
+/// </summary>
+public sealed class NotificationAttemptLease : IDisposable
+{
+    private readonly SemaphoreSlim workItemGate;
+    private bool disposed;
+
+    internal NotificationAttemptLease(SemaphoreSlim workItemGate, bool shouldNotify)
+    {
+        this.workItemGate = workItemGate;
+        ShouldNotify = shouldNotify;
+    }
+
+    /// <summary>
+    /// 取得本輪是否應呼叫通知 Gateway。
+    /// </summary>
+    public bool ShouldNotify { get; }
+
+    /// <inheritdoc />
+    public void Dispose()
+    {
+        if (disposed)
+        {
+            return;
+        }
+
+        disposed = true;
+        workItemGate.Release();
+    }
+}
+
+/// <summary>
+/// 以逐工作項目鎖定與重疊 Session 判斷，協調逾期通知嘗試。
+/// </summary>
+public sealed class OverdueProcessingConcurrencyCoordinator
+    : IOverdueProcessingConcurrencyCoordinator
+{
+    private readonly object stateLock = new();
+    private readonly ConcurrentDictionary<Guid, SemaphoreSlim> workItemGates = new();
+    private readonly Dictionary<Guid, ProcessingSessionState> lastNotificationSessions = new();
+    private long eventSequence;
+
+    /// <inheritdoc />
+    public IOverdueProcessingSession BeginSession()
+    {
+        lock (stateLock)
+        {
+            return new ProcessingSession(
+                this,
+                new ProcessingSessionState(++eventSequence));
+        }
+    }
+
+    private async Task<NotificationAttemptLease> EnterNotificationAttemptAsync(
+        ProcessingSessionState session,
+        Guid workItemId,
+        CancellationToken cancellationToken)
+    {
+        var workItemGate = workItemGates.GetOrAdd(
+            workItemId,
+            static _ => new SemaphoreSlim(1, 1));
+        await workItemGate.WaitAsync(cancellationToken);
+
+        try
+        {
+            lock (stateLock)
+            {
+                if (lastNotificationSessions.TryGetValue(workItemId, out var lastSession) &&
+                    SessionsOverlap(lastSession, session))
+                {
+                    return new NotificationAttemptLease(workItemGate, shouldNotify: false);
+                }
+
+                // 在呼叫外部 Gateway 前登記，涵蓋成功回應遺失後的重疊重試競態。
+                lastNotificationSessions[workItemId] = session;
+                return new NotificationAttemptLease(workItemGate, shouldNotify: true);
+            }
+        }
+        catch
+        {
+            workItemGate.Release();
+            throw;
+        }
+    }
+
+    private void EndSession(ProcessingSessionState session)
+    {
+        lock (stateLock)
+        {
+            session.EndEvent ??= ++eventSequence;
+        }
+    }
+
+    private static bool SessionsOverlap(
+        ProcessingSessionState previousSession,
+        ProcessingSessionState currentSession) =>
+        previousSession.EndEvent is null ||
+        previousSession.EndEvent.Value >= currentSession.StartEvent;
+
+    private sealed class ProcessingSession(
+        OverdueProcessingConcurrencyCoordinator coordinator,
+        ProcessingSessionState state) : IOverdueProcessingSession
+    {
+        private bool disposed;
+
+        public Task<NotificationAttemptLease> EnterNotificationAttemptAsync(
+            Guid workItemId,
+            CancellationToken cancellationToken)
+        {
+            ObjectDisposedException.ThrowIf(disposed, this);
+            return coordinator.EnterNotificationAttemptAsync(
+                state,
+                workItemId,
+                cancellationToken);
+        }
+
+        public void Dispose()
+        {
+            if (disposed)
+            {
+                return;
+            }
+
+            disposed = true;
+            coordinator.EndSession(state);
+        }
+    }
+
+    private sealed class ProcessingSessionState(long startEvent)
+    {
+        public long StartEvent { get; } = startEvent;
+
+        public long? EndEvent { get; set; }
+    }
+}
