+using System.Net;
+using System.Net.Http.Json;
+using Microsoft.Extensions.DependencyInjection;
+using Microsoft.Extensions.Logging.Abstractions;
+using Microsoft.Extensions.Options;
+using WorkItems.Api.Data;
+using WorkItems.Api.Models;
+using Xunit;
+
+namespace WorkItems.Api.Tests;
+
+public sealed class ConcurrentOverdueProcessingTests
+{
+    [Fact]
+    public async Task HttpAndBackgroundWorker_WhenProcessingSameWorkItemConcurrently_NotifyOnce()
+    {
+        var cancellationToken = TestContext.Current.CancellationToken;
+        var notificationStarted = new TaskCompletionSource(
+            TaskCreationOptions.RunContinuationsAsynchronously);
+        var releaseNotification = new TaskCompletionSource(
+            TaskCreationOptions.RunContinuationsAsynchronously);
+        var coordinator = new ObservableConcurrencyCoordinator(
+            new OverdueProcessingConcurrencyCoordinator(),
+            expectedSessionCount: 2);
+
+        using var factory = new WorkItemsApiFactory(
+            notificationHandler: async (_, token) =>
+            {
+                notificationStarted.TrySetResult();
+                await releaseNotification.Task.WaitAsync(token);
+                return true;
+            },
+            concurrencyCoordinator: coordinator);
+        using var client = factory.CreateClient();
+        var workItem = CreateDueWorkItem(factory.UtcNow);
+        await SeedAsync(factory, workItem, cancellationToken);
+
+        var worker = new OverdueProcessingWorker(
+            factory.Services.GetRequiredService<IServiceScopeFactory>(),
+            Options.Create(new OverdueProcessingOptions
+            {
+                Enabled = true,
+                IntervalSeconds = 60
+            }),
+            TimeProvider.System,
+            NullLogger<OverdueProcessingWorker>.Instance);
+
+        try
+        {
+            await worker.StartAsync(cancellationToken);
+            await notificationStarted.Task.WaitAsync(cancellationToken);
+
+            var httpResponseTask = client.PostAsync(
+                "/api/work-items/process-overdue",
+                null,
+                cancellationToken);
+            await coordinator.ExpectedSessionsStarted.WaitAsync(cancellationToken);
+            releaseNotification.TrySetResult();
+
+            using var response = await httpResponseTask;
+            var summary = await response.Content.ReadFromJsonAsync<ProcessOverdueContract>(
+                cancellationToken: cancellationToken);
+
+            Assert.Equal(HttpStatusCode.OK, response.StatusCode);
+            Assert.NotNull(summary);
+            Assert.Equal(0, summary.NotificationAttemptCount);
+            Assert.Equal([workItem.Id], factory.Notifications.AttemptedWorkItemIds);
+        }
+        finally
+        {
+            releaseNotification.TrySetResult();
+            await worker.StopAsync(cancellationToken);
+            worker.Dispose();
+        }
+    }
+
+    [Fact]
+    public async Task ConcurrentProcessing_WhenNotificationAcknowledgementIsLost_RetriesAfterOverlapEnds()
+    {
+        var cancellationToken = TestContext.Current.CancellationToken;
+        var notificationStarted = new TaskCompletionSource(
+            TaskCreationOptions.RunContinuationsAsynchronously);
+        var releaseLostAcknowledgement = new TaskCompletionSource(
+            TaskCreationOptions.RunContinuationsAsynchronously);
+        var coordinator = new ObservableConcurrencyCoordinator(
+            new OverdueProcessingConcurrencyCoordinator(),
+            expectedSessionCount: 2);
+        var notificationCallCount = 0;
+
+        using var factory = new WorkItemsApiFactory(
+            notificationHandler: async (_, token) =>
+            {
+                var callNumber = Interlocked.Increment(ref notificationCallCount);
+                if (callNumber == 1)
+                {
+                    notificationStarted.TrySetResult();
+                    await releaseLostAcknowledgement.Task.WaitAsync(token);
+                    throw new InvalidOperationException("通知已送出，但未收到 ACK。");
+                }
+
+                return true;
+            },
+            concurrencyCoordinator: coordinator);
+        _ = factory.CreateClient();
+        var workItem = CreateDueWorkItem(factory.UtcNow);
+        await SeedAsync(factory, workItem, cancellationToken);
+
+        await using var firstScope = factory.Services.CreateAsyncScope();
+        await using var overlappingScope = factory.Services.CreateAsyncScope();
+        var firstProcessor = firstScope.ServiceProvider
+            .GetRequiredService<IOverdueWorkItemProcessor>();
+        var overlappingProcessor = overlappingScope.ServiceProvider
+            .GetRequiredService<IOverdueWorkItemProcessor>();
+
+        var firstProcessing = firstProcessor.ProcessAsync(cancellationToken);
+        await notificationStarted.Task.WaitAsync(cancellationToken);
+        var overlappingProcessing = overlappingProcessor.ProcessAsync(cancellationToken);
+        await coordinator.ExpectedSessionsStarted.WaitAsync(cancellationToken);
+        releaseLostAcknowledgement.TrySetResult();
+
+        var exception = await Assert.ThrowsAsync<InvalidOperationException>(
+            () => firstProcessing);
+        var overlappingSummary = await overlappingProcessing;
+
+        Assert.Equal("通知已送出，但未收到 ACK。", exception.Message);
+        Assert.Equal(0, overlappingSummary.NotificationAttemptCount);
+        Assert.Equal(1, notificationCallCount);
+
+        await using var retryScope = factory.Services.CreateAsyncScope();
+        var retryProcessor = retryScope.ServiceProvider
+            .GetRequiredService<IOverdueWorkItemProcessor>();
+        var retrySummary = await retryProcessor.ProcessAsync(cancellationToken);
+
+        Assert.Equal(1, retrySummary.NotificationAttemptCount);
+        Assert.Equal(2, notificationCallCount);
+        Assert.Equal([workItem.Id, workItem.Id], factory.Notifications.AttemptedWorkItemIds);
+    }
+
+    private static WorkItem CreateDueWorkItem(DateTimeOffset utcNow) =>
+        new()
+        {
+            Id = Guid.NewGuid(),
+            Title = "並行通知測試",
+            Priority = "Normal",
+            DueAtUtc = utcNow.AddHours(-1),
+            CreatedAtUtc = utcNow.AddDays(-1)
+        };
+
+    private static async Task SeedAsync(
+        WorkItemsApiFactory factory,
+        WorkItem workItem,
+        CancellationToken cancellationToken)
+    {
+        await using var scope = factory.Services.CreateAsyncScope();
+        var database = scope.ServiceProvider.GetRequiredService<WorkItemsDbContext>();
+        database.WorkItems.Add(workItem);
+        await database.SaveChangesAsync(cancellationToken);
+    }
+
+    private sealed class ObservableConcurrencyCoordinator(
+        IOverdueProcessingConcurrencyCoordinator innerCoordinator,
+        int expectedSessionCount) : IOverdueProcessingConcurrencyCoordinator
+    {
+        private readonly TaskCompletionSource expectedSessionsStarted = new(
+            TaskCreationOptions.RunContinuationsAsynchronously);
+        private int sessionCount;
+
+        public Task ExpectedSessionsStarted => expectedSessionsStarted.Task;
+
+        public IOverdueProcessingSession BeginSession()
+        {
+            var session = innerCoordinator.BeginSession();
+            if (Interlocked.Increment(ref sessionCount) >= expectedSessionCount)
+            {
+                expectedSessionsStarted.TrySetResult();
+            }
+
+            return session;
+        }
+    }
+
+    private sealed record ProcessOverdueContract(
+        int ProcessedCount,
+        int NotificationAttemptCount,
+        int NotificationFailureCount,
+        Guid[] FailedNotificationWorkItemIds);
+}

