@@ -0,0 +1,34 @@
+namespace WorkItems.Api;
+
+/// <summary>
+/// 協調同一個應用程式執行個體內的逾期批次，避免重疊批次重複送出通知。
+/// </summary>
+public sealed class OverdueProcessingCoordinator
+{
+    private readonly SemaphoreSlim processingSemaphore = new(1, 1);
+
+    /// <summary>
+    /// 嘗試取得逾期批次的單次執行租約，不等待目前進行中的批次完成。
+    /// </summary>
+    /// <param name="cancellationToken">取消權杖。</param>
+    /// <returns>取得租約時回傳可釋放物件；已有批次進行中時回傳 <see langword="null"/>。</returns>
+    public IDisposable? TryEnter(CancellationToken cancellationToken)
+    {
+        if (!processingSemaphore.Wait(0, cancellationToken))
+        {
+            return null;
+        }
+
+        return new ProcessingLease(processingSemaphore);
+    }
+
+    private sealed class ProcessingLease(SemaphoreSlim processingSemaphore) : IDisposable
+    {
+        private SemaphoreSlim? semaphore = processingSemaphore;
+
+        public void Dispose()
+        {
+            Interlocked.Exchange(ref semaphore, null)?.Release();
+        }
+    }
+}

