new file mode 100644
index 0000000..33393b8
--- /dev/null
+++ b/src/WorkItems.Api/InFlightWorkItemNotificationRegistry.cs
@@ -0,0 +1,48 @@
+namespace WorkItems.Api;
+
+/// <summary>
+/// 記錄目前正在嘗試通知的工作項目，避免同一個應用程式執行個體重複送出並行通知。
+/// </summary>
+public sealed class InFlightWorkItemNotificationRegistry
+{
+    private readonly Lock synchronization = new();
+    private readonly HashSet<Guid> registeredWorkItemIds = [];
+
+    /// <summary>
+    /// 嘗試登記工作項目的通知處理權。
+    /// </summary>
+    /// <param name="workItemId">工作項目識別碼。</param>
+    /// <returns>登記成功時回傳可釋放的登記；已有通知進行中時回傳 <see langword="null"/>。</returns>
+    public IDisposable? TryRegister(Guid workItemId)
+    {
+        lock (synchronization)
+        {
+            if (!registeredWorkItemIds.Add(workItemId))
+            {
+                return null;
+            }
+        }
+
+        return new Registration(this, workItemId);
+    }
+
+    private void Unregister(Guid workItemId)
+    {
+        lock (synchronization)
+        {
+            registeredWorkItemIds.Remove(workItemId);
+        }
+    }
+
+    private sealed class Registration(
+        InFlightWorkItemNotificationRegistry registry,
+        Guid workItemId) : IDisposable
+    {
+        private InFlightWorkItemNotificationRegistry? owner = registry;
+
+        public void Dispose()
+        {
+            Interlocked.Exchange(ref owner, null)?.Unregister(workItemId);
+        }
+    }
+}
