+
+public sealed class ConcurrentOverdueProcessingTests
+{
+    [Fact]
+    public async Task HttpAndWorker_WhenProcessingSameWorkItemConcurrently_SendOneNotification()
+    {
+        var cancellationToken = TestContext.Current.CancellationToken;
+        var notificationStarted = new TaskCompletionSource(
+            TaskCreationOptions.RunContinuationsAsynchronously);
+        var allowNotificationToComplete = new TaskCompletionSource(
+            TaskCreationOptions.RunContinuationsAsynchronously);
+        using var factory = new WorkItemsApiFactory(
+            notificationHandler: async (_, token) =>
+            {
+                notificationStarted.TrySetResult();
+                await allowNotificationToComplete.Task.WaitAsync(token);
+                return true;
+            });
+        using var client = factory.CreateClient();
+        var workItem = CreateDueWorkItem(factory.UtcNow);
+        await SeedAsync(factory, workItem, cancellationToken);
+        var worker = new OverdueProcessingWorker(
+            factory.Services.GetRequiredService<IServiceScopeFactory>(),
+            Options.Create(new OverdueProcessingOptions
+            {
+                Enabled = true,
+                IntervalSeconds = 60
+            }),
+            TimeProvider.System,
+            NullLogger<OverdueProcessingWorker>.Instance);
+
+        await worker.StartAsync(cancellationToken);
+        await notificationStarted.Task.WaitAsync(cancellationToken);
+        var httpResponseTask = client.PostAsync(
+            "/api/work-items/process-overdue",
+            null,
+            cancellationToken);
+        var completedWhileWorkerNotificationWasInFlight =
+            await Task.WhenAny(
+                httpResponseTask,
+                Task.Delay(TimeSpan.FromSeconds(2), cancellationToken)) == httpResponseTask;
+
+        allowNotificationToComplete.TrySetResult();
+        using var response = await httpResponseTask;
+        var persistedStatus = await WaitForStatusAsync(
+            factory,
+            workItem.Id,
+            "Overdue",
+            cancellationToken);
+        await worker.StopAsync(cancellationToken);
+
+        var summary = await response.Content.ReadFromJsonAsync<ProcessOverdueResponse>(
+            cancellationToken: cancellationToken);
+        Assert.True(completedWhileWorkerNotificationWasInFlight);
+        Assert.Equal(HttpStatusCode.OK, response.StatusCode);
+        Assert.NotNull(summary);
+        Assert.Equal(0, summary.NotificationAttemptCount);
+        Assert.Equal([workItem.Id], factory.Notifications.AttemptedWorkItemIds);
+        Assert.Equal("Overdue", persistedStatus);
+    }
+
+    [Fact]
+    public async Task NotificationSucceededButPersistenceAckWasCanceled_ReleasesItemForRetry()
+    {
+        var cancellationToken = TestContext.Current.CancellationToken;
+        CancellationTokenSource? lostAckCancellation = null;
+        var notificationAttempt = 0;
+        using var factory = new WorkItemsApiFactory(
+            notificationHandler: (_, _) =>
+            {
+                if (Interlocked.Increment(ref notificationAttempt) == 1)
+                {
+                    lostAckCancellation!.Cancel();
+                }
+
+                return Task.FromResult(true);
+            });
+        var workItem = CreateDueWorkItem(factory.UtcNow);
+        await SeedAsync(factory, workItem, cancellationToken);
+
+        using (lostAckCancellation = new CancellationTokenSource())
+        {
+            await using var firstScope = factory.Services.CreateAsyncScope();
+            var firstProcessor = firstScope.ServiceProvider
+                .GetRequiredService<IOverdueWorkItemProcessor>();
+
+            await Assert.ThrowsAnyAsync<OperationCanceledException>(
+                () => firstProcessor.ProcessAsync(lostAckCancellation.Token));
+        }
+
+        Assert.Equal("Open", await ReadStatusAsync(factory, workItem.Id, cancellationToken));
+
+        await using var retryScope = factory.Services.CreateAsyncScope();
+        var retryProcessor = retryScope.ServiceProvider
+            .GetRequiredService<IOverdueWorkItemProcessor>();
+        var retrySummary = await retryProcessor.ProcessAsync(cancellationToken);
+
+        Assert.Equal(1, retrySummary.NotificationAttemptCount);
+        Assert.Equal([workItem.Id, workItem.Id], factory.Notifications.AttemptedWorkItemIds);
+        Assert.Equal("Overdue", await ReadStatusAsync(factory, workItem.Id, cancellationToken));
+    }
+
+    private static WorkItem CreateDueWorkItem(DateTimeOffset currentUtc) =>
+        new()
+        {
+            Id = Guid.NewGuid(),
+            Title = "HTTP 與 Worker 競態通知",
+            Priority = "Normal",
+            DueAtUtc = currentUtc.AddHours(-1),
+            CreatedAtUtc = currentUtc.AddDays(-1)
+        };
+
+    private static async Task SeedAsync(
+        WorkItemsApiFactory factory,
+        WorkItem workItem,
+        CancellationToken cancellationToken)
+    {
+        await using var scope = factory.Services.CreateAsyncScope();
+        var database = scope.ServiceProvider.GetRequiredService<WorkItemsDbContext>();
+        database.WorkItems.Add(workItem);
+        await database.SaveChangesAsync(cancellationToken);
+    }
+
+    private static async Task<string> ReadStatusAsync(
+        WorkItemsApiFactory factory,
+        Guid workItemId,
+        CancellationToken cancellationToken)
+    {
+        await using var scope = factory.Services.CreateAsyncScope();
+        var database = scope.ServiceProvider.GetRequiredService<WorkItemsDbContext>();
+        return await database.WorkItems
+            .AsNoTracking()
+            .Where(workItem => workItem.Id == workItemId)
+            .Select(workItem => workItem.Status)
+            .SingleAsync(cancellationToken);
+    }
+
+    private static async Task<string> WaitForStatusAsync(
+        WorkItemsApiFactory factory,
+        Guid workItemId,
+        string expectedStatus,
+        CancellationToken cancellationToken)
+    {
+        using var timeout = new CancellationTokenSource(TimeSpan.FromSeconds(2));
+        using var linkedCancellation = CancellationTokenSource.CreateLinkedTokenSource(
+            cancellationToken,
+            timeout.Token);
+
+        while (true)
+        {
+            var status = await ReadStatusAsync(
+                factory,
+                workItemId,
+                linkedCancellation.Token);
+            if (status == expectedStatus)
+            {
+                return status;
+            }
+
+            await Task.Delay(TimeSpan.FromMilliseconds(10), linkedCancellation.Token);
+        }
+    }
+}

