@@ -0,0 +1,98 @@
+using System.Runtime.ExceptionServices;
+using WorkItems.Api.Contracts;
+
+namespace WorkItems.Api;
+
+/// <summary>
+/// 協調重疊的逾期處理要求，使它們共用同一次完成結果。
+/// </summary>
+public sealed class OverdueProcessingExecutionCoordinator
+{
+    private readonly object synchronization = new();
+    private Task<ExecutionOutcome>? activeExecution;
+
+    /// <summary>
+    /// 執行逾期處理；若另一個執行在等待期間完成，則重播該次結果。
+    /// </summary>
+    /// <param name="execute">取得鎖後要執行的逾期處理。</param>
+    /// <param name="cancellationToken">等待與處理使用的取消權杖。</param>
+    /// <returns>本次執行或重疊執行的處理摘要。</returns>
+    public Task<ProcessOverdueResponse> ExecuteAsync(
+        Func<Task<ProcessOverdueResponse>> execute,
+        CancellationToken cancellationToken)
+    {
+        TaskCompletionSource<ExecutionOutcome>? ownedExecution = null;
+        Task<ExecutionOutcome> executionToAwait;
+
+        lock (synchronization)
+        {
+            if (activeExecution is null)
+            {
+                ownedExecution = new TaskCompletionSource<ExecutionOutcome>(
+                    TaskCreationOptions.RunContinuationsAsynchronously);
+                activeExecution = ownedExecution.Task;
+            }
+
+            executionToAwait = activeExecution;
+        }
+
+        return ownedExecution is null
+            ? AwaitExistingExecutionAsync(executionToAwait, cancellationToken)
+            : ExecuteOwnedAsync(ownedExecution, execute);
+    }
+
+    private async Task<ProcessOverdueResponse> ExecuteOwnedAsync(
+        TaskCompletionSource<ExecutionOutcome> completion,
+        Func<Task<ProcessOverdueResponse>> execute)
+    {
+        ExecutionOutcome outcome;
+
+        try
+        {
+            outcome = ExecutionOutcome.Succeeded(await execute());
+        }
+        catch (Exception exception)
+        {
+            outcome = ExecutionOutcome.Failed(exception);
+        }
+
+        completion.SetResult(outcome);
+
+        lock (synchronization)
+        {
+            if (ReferenceEquals(activeExecution, completion.Task))
+            {
+                activeExecution = null;
+            }
+        }
+
+        return outcome.GetResponse();
+    }
+
+    private static async Task<ProcessOverdueResponse> AwaitExistingExecutionAsync(
+        Task<ExecutionOutcome> activeExecution,
+        CancellationToken cancellationToken)
+    {
+        var outcome = await activeExecution.WaitAsync(cancellationToken);
+        return outcome.GetResponse();
+    }
+
+    private sealed record ExecutionOutcome(
+        ProcessOverdueResponse? Response,
+        ExceptionDispatchInfo? Exception)
+    {
+        public static ExecutionOutcome Succeeded(ProcessOverdueResponse response) =>
+            new(response, null);
+
+        public static ExecutionOutcome Failed(Exception exception) =>
+            new(null, ExceptionDispatchInfo.Capture(exception));
+
+        public ProcessOverdueResponse GetResponse()
+        {
+            Exception?.Throw();
+
+            return Response ?? throw new InvalidOperationException(
+                "找不到已完成逾期處理的結果。");
+        }
+    }
+}
