+        var concurrentHttpProcessing = client.PostAsync(
+            "/api/work-items/process-overdue",
+            null,
+            cancellationToken);
+        await invocations.SecondInvocation.WaitAsync(cancellationToken);
+
+        releaseLostAcknowledgement.TrySetResult();
+        using var lostAcknowledgementResponse = await concurrentHttpProcessing;
+        await worker.StopAsync(cancellationToken);
+
+        Assert.Equal(HttpStatusCode.InternalServerError, lostAcknowledgementResponse.StatusCode);
+        Assert.Single(factory.Notifications.AttemptedWorkItemIds);
