+        database.WorkItems.Add(new WorkItem
+        {
+            Id = Guid.NewGuid(),
+            Title = "HTTP 與 Worker 同時處理",
+            Priority = "Normal",
+            DueAtUtc = factory.UtcNow.AddHours(-1),
+            CreatedAtUtc = factory.UtcNow.AddDays(-1)
