@@ -0,0 +1,90 @@
+using WorkItems.Api.Contracts;
+
+namespace WorkItems.Api;
+
+/// <summary>
+/// 合併同一應用程式執行個體內彼此重疊的逾期處理呼叫。
+/// </summary>
+public sealed class OverdueProcessingCoordinator
+{
+    private readonly object synchronizationRoot = new();
+    private ProcessingOperation? activeOperation;
+
+    /// <summary>
+    /// 執行逾期處理；已有批次進行中時，共用該批次的結果。
+    /// </summary>
+    /// <param name="processAsync">實際逾期處理工作。</param>
+    /// <param name="cancellationToken">呼叫端的取消權杖。</param>
+    /// <returns>本次共同批次的處理摘要。</returns>
+    public Task<ProcessOverdueResponse> ExecuteAsync(
+        Func<CancellationToken, Task<ProcessOverdueResponse>> processAsync,
+        CancellationToken cancellationToken)
+    {
+        ArgumentNullException.ThrowIfNull(processAsync);
+
+        ProcessingOperation operation;
+        var startsOperation = false;
+
+        lock (synchronizationRoot)
+        {
+            if (activeOperation is null)
+            {
+                activeOperation = new ProcessingOperation();
+                startsOperation = true;
+            }
+
+            operation = activeOperation;
+        }
+
+        if (startsOperation)
+        {
+            _ = ExecuteAndCompleteAsync(operation, processAsync, cancellationToken);
+        }
+
+        return operation.Completion.WaitAsync(cancellationToken);
+    }
+
+    private async Task ExecuteAndCompleteAsync(
+        ProcessingOperation operation,
+        Func<CancellationToken, Task<ProcessOverdueResponse>> processAsync,
+        CancellationToken cancellationToken)
+    {
+        try
+        {
+            var response = await processAsync(cancellationToken);
+            operation.SetResult(response);
+        }
+        catch (OperationCanceledException exception)
+        {
+            operation.SetException(exception);
+        }
+        catch (Exception exception)
+        {
+            operation.SetException(exception);
+        }
+        finally
+        {
+            lock (synchronizationRoot)
+            {
+                if (ReferenceEquals(activeOperation, operation))
+                {
+                    activeOperation = null;
+                }
+            }
+        }
+    }
+
+    private sealed class ProcessingOperation
+    {
+        private readonly TaskCompletionSource<ProcessOverdueResponse> completionSource =
+            new(TaskCreationOptions.RunContinuationsAsynchronously);
+
+        public Task<ProcessOverdueResponse> Completion => completionSource.Task;
+
+        public void SetResult(ProcessOverdueResponse response) =>
+            completionSource.TrySetResult(response);
+
+        public void SetException(Exception exception) =>
+            completionSource.TrySetException(exception);
+    }
+}
