+        var releaseNotification = CreateSignal();
+        WorkItemsApiFactory? factoryForCallback = null;
+        string? persistedStatusDuringNotification = null;
+        var externalSideEffectCount = 0;
+
+        using var factory = new WorkItemsApiFactory(
+            notificationHandler: async (workItem, token) =>
+            {
+                Interlocked.Increment(ref externalSideEffectCount);
+                await using var scope = factoryForCallback!.Services.CreateAsyncScope();
+                var database = scope.ServiceProvider.GetRequiredService<WorkItemsDbContext>();
+                persistedStatusDuringNotification = await database.WorkItems
+                    .AsNoTracking()
+                    .Where(candidate => candidate.Id == workItem.Id)
+                    .Select(candidate => candidate.Status)
+                    .SingleAsync(token);
+                notificationStarted.TrySetResult();
+                await releaseNotification.Task.WaitAsync(token);
+                return true;
+            });
+        factoryForCallback = factory;
+
+        using var client = factory.CreateClient();
+        var workItem = CreateDueWorkItem(factory.UtcNow, "HTTP 與 Worker 競態");
+        await SeedAsync(factory, workItem, cancellationToken);
+
+        var httpProcessing = client.PostAsync(
+            "/api/work-items/process-overdue",
+            null,
+            cancellationToken);
+        await notificationStarted.Task.WaitAsync(cancellationToken);
+
+        using var worker = CreateWorker(factory.Services);
+        await worker.StartAsync(cancellationToken);
+
+        try
+        {
+            Assert.Equal(1, Volatile.Read(ref externalSideEffectCount));
+            Assert.False(httpProcessing.IsCompleted);
+            releaseNotification.TrySetResult();
+
+            using var response = await httpProcessing;
+            Assert.Equal(HttpStatusCode.OK, response.StatusCode);
+        }
+        finally
+        {
+            releaseNotification.TrySetResult();
+            await worker.StopAsync(cancellationToken);
+        }
+
+        Assert.Equal("Open", persistedStatusDuringNotification);
+        Assert.Equal("Overdue", await ReadStatusAsync(factory, workItem.Id, cancellationToken));
+        Assert.Equal(1, Volatile.Read(ref externalSideEffectCount));
+
+        using var retryResponse = await client.PostAsync(
+            "/api/work-items/process-overdue",
+            null,
+            cancellationToken);
+
+        Assert.Equal(HttpStatusCode.OK, retryResponse.StatusCode);
+        Assert.Equal(2, Volatile.Read(ref externalSideEffectCount));
+    }
+
+    [Fact]
+    public async Task HttpAndWorker_WhenAcknowledgementIsLost_ShareFailureAndNextRunRetries()
+    {
+        var cancellationToken = TestContext.Current.CancellationToken;
+        var notificationStarted = CreateSignal();
+        var loseAcknowledgement = CreateSignal();
+        var externalSideEffectCount = 0;
+
+        using var factory = new WorkItemsApiFactory(
+            notificationHandler: async (_, token) =>
+            {
+                var attempt = Interlocked.Increment(ref externalSideEffectCount);
+                if (attempt == 1)
+                {
+                    notificationStarted.TrySetResult();
+                    await loseAcknowledgement.Task.WaitAsync(token);
+                    throw new InvalidOperationException("通知已送出，但未收到 ACK。");
+                }
+
+                return true;
+            });
+        using var client = factory.CreateClient();
+        var workItem = CreateDueWorkItem(factory.UtcNow, "Lost ACK");
+        await SeedAsync(factory, workItem, cancellationToken);
+
+        var httpProcessing = client.PostAsync(
+            "/api/work-items/process-overdue",
+            null,
+            cancellationToken);
+        await notificationStarted.Task.WaitAsync(cancellationToken);
+
+        using var worker = CreateWorker(factory.Services);
+        await worker.StartAsync(cancellationToken);
+
+        try
+        {
+            Assert.Equal(1, Volatile.Read(ref externalSideEffectCount));
+            loseAcknowledgement.TrySetResult();
+
+            using var failedResponse = await httpProcessing;
+            Assert.Equal(HttpStatusCode.InternalServerError, failedResponse.StatusCode);
+        }
+        finally
+        {
+            loseAcknowledgement.TrySetResult();
+            await worker.StopAsync(cancellationToken);
+        }
+
+        Assert.Equal(1, Volatile.Read(ref externalSideEffectCount));
+        Assert.Equal("Open", await ReadStatusAsync(factory, workItem.Id, cancellationToken));
+
+        using var retryResponse = await client.PostAsync(
+            "/api/work-items/process-overdue",
+            null,
+            cancellationToken);
+
+        Assert.Equal(HttpStatusCode.OK, retryResponse.StatusCode);
+        Assert.Equal(2, Volatile.Read(ref externalSideEffectCount));
+        Assert.Equal("Overdue", await ReadStatusAsync(factory, workItem.Id, cancellationToken));
+    }
+
+    private static TaskCompletionSource CreateSignal() =>
+        new(TaskCreationOptions.RunContinuationsAsynchronously);
+
+    private static OverdueProcessingWorker CreateWorker(IServiceProvider serviceProvider) =>
+        new(
+            serviceProvider.GetRequiredService<IServiceScopeFactory>(),
+            Options.Create(
+                new OverdueProcessingOptions
+                {
+                    Enabled = true,
+                    IntervalSeconds = 60
+                }),
+            TimeProvider.System,
+            NullLogger<OverdueProcessingWorker>.Instance);
+
+    private static WorkItem CreateDueWorkItem(DateTimeOffset utcNow, string title) =>
+        new()
+        {
+            Id = Guid.NewGuid(),
+            Title = title,
+            Priority = "Normal",
+            DueAtUtc = utcNow.AddHours(-1),
+            CreatedAtUtc = utcNow.AddDays(-1)
+        };
+
+    private static async Task SeedAsync(
+        WorkItemsApiFactory factory,
+        WorkItem workItem,
+        CancellationToken cancellationToken)
+    {
+        await using var scope = factory.Services.CreateAsyncScope();
+        var database = scope.ServiceProvider.GetRequiredService<WorkItemsDbContext>();
+        database.WorkItems.Add(workItem);
+        await database.SaveChangesAsync(cancellationToken);
+    }
+
+    private static async Task<string> ReadStatusAsync(
+        WorkItemsApiFactory factory,
+        Guid workItemId,
+        CancellationToken cancellationToken)
+    {
+        await using var scope = factory.Services.CreateAsyncScope();
+        var database = scope.ServiceProvider.GetRequiredService<WorkItemsDbContext>();
+        return await database.WorkItems
+            .AsNoTracking()
+            .Where(workItem => workItem.Id == workItemId)
+            .Select(workItem => workItem.Status)
+            .SingleAsync(cancellationToken);
+    }
+}

