diff --git a/src/WorkItems.Api/WorkItemProcessingClaimRegistry.cs b/src/WorkItems.Api/WorkItemProcessingClaimRegistry.cs
new file mode 100644
index 0000000..68f8d6b
--- /dev/null
+++ b/src/WorkItems.Api/WorkItemProcessingClaimRegistry.cs
@@ -0,0 +1,43 @@
+using System.Collections.Concurrent;
+
+namespace WorkItems.Api;
+
+/// <summary>
+/// 記錄目前正在處理通知的工作項目，避免同一個應用程式實例重複送出並行通知。
+/// </summary>
+public sealed class WorkItemProcessingClaimRegistry
+{
+    private readonly ConcurrentDictionary<Guid, byte> activeWorkItemIds = new();
+
+    /// <summary>
+    /// 嘗試取得工作項目的處理權；已由其他流程處理時不等待。
+    /// </summary>
+    /// <param name="workItemId">工作項目識別碼。</param>
+    /// <returns>取得處理權時回傳必須釋放的 Claim；否則回傳 <see langword="null"/>。</returns>
+    internal IDisposable? TryAcquire(Guid workItemId)
+    {
+        return activeWorkItemIds.TryAdd(workItemId, 0)
+            ? new ProcessingClaim(this, workItemId)
+            : null;
+    }
+
+    private void Release(Guid workItemId)
+    {
+        _ = activeWorkItemIds.TryRemove(workItemId, out _);
+    }
+
+    private sealed class ProcessingClaim(
+        WorkItemProcessingClaimRegistry registry,
+        Guid workItemId) : IDisposable
+    {
+        private int disposed;
+
+        public void Dispose()
+        {
+            if (Interlocked.Exchange(ref disposed, 1) == 0)
+            {
+                registry.Release(workItemId);
+            }
+        }
+    }
+}

