+using Microsoft.Extensions.Options;
+using WorkItems.Api.Models;
+using WorkItems.Api.Notifications;
+using Xunit;
+
+namespace WorkItems.Api.Tests;
+
+/// <summary>
+/// 驗證通知 Provider 對 Use Case 提供的共同契約。
+/// </summary>
+public abstract class NotificationProviderContractTests
+{
+    private const string FailureTitleMarker = "[通知失敗]";
+
+    /// <summary>
+    /// 建立要驗證的 Provider。
+    /// </summary>
+    /// <returns>通知 Provider。</returns>
+    protected abstract INotificationProvider CreateProvider();
+
+    [Theory]
+    [InlineData(false)]
+    [InlineData(true)]
+    public async Task SendAsync_WhenProviderAcceptsNotification_ReturnsTrue(bool escalation)
+    {
+        var cancellationToken = TestContext.Current.CancellationToken;
+        var provider = CreateProvider();
+        var workItem = CreateWorkItem("契約通知成功");
+
+        var succeeded = await SendAsync(provider, workItem, escalation, cancellationToken);
+
+        Assert.True(succeeded);
+    }
+
+    [Theory]
+    [InlineData(false)]
+    [InlineData(true)]
+    public async Task SendAsync_WhenProviderRejectsNotification_ReturnsFalse(bool escalation)
+    {
+        var cancellationToken = TestContext.Current.CancellationToken;
+        var provider = CreateProvider();
+        var workItem = CreateWorkItem($"契約{FailureTitleMarker}通知失敗");
+
+        var succeeded = await SendAsync(provider, workItem, escalation, cancellationToken);
+
+        Assert.False(succeeded);
+    }
+
+    [Theory]
+    [InlineData(false)]
+    [InlineData(true)]
+    public async Task SendAsync_WhenCanceled_PropagatesCancellation(bool escalation)
+    {
+        var provider = CreateProvider();
+        var workItem = CreateWorkItem("契約通知取消");
+        using var cancellationSource = new CancellationTokenSource();
+        await cancellationSource.CancelAsync();
+
+        var exception = await Assert.ThrowsAsync<OperationCanceledException>(
+            () => SendAsync(provider, workItem, escalation, cancellationSource.Token));
+
+        Assert.Equal(cancellationSource.Token, exception.CancellationToken);
+    }
+
+    private static Task<bool> SendAsync(
+        INotificationProvider provider,
+        WorkItem workItem,
+        bool escalation,
+        CancellationToken cancellationToken) =>
+        escalation
+            ? provider.SendEscalationAsync(workItem, cancellationToken)
+            : provider.SendOverdueAsync(workItem, cancellationToken);
+
+    private static WorkItem CreateWorkItem(string title) =>
+        new()
+        {
+            Id = Guid.NewGuid(),
+            Title = title,
+            Priority = "Normal",
+            DueAtUtc = new DateTimeOffset(2026, 9, 1, 7, 0, 0, TimeSpan.Zero),
+            CreatedAtUtc = new DateTimeOffset(2026, 8, 31, 7, 0, 0, TimeSpan.Zero)
+        };
+
+    /// <summary>
+    /// 取得 Contract Test 所使用的通知失敗標記。
+    /// </summary>
+    protected static string ConfiguredFailureTitleMarker => FailureTitleMarker;
+}
+
+/// <summary>
+/// 驗證 Demo 通知 Provider 符合共同契約。
+/// </summary>
+public sealed class DemoNotificationProviderContractTests : NotificationProviderContractTests
+{
+    /// <inheritdoc />
+    protected override INotificationProvider CreateProvider() =>
+        new DemoNotificationProvider(
+            Options.Create(
+                new DemoNotificationOptions
+                {
+                    FailureTitleMarker = ConfiguredFailureTitleMarker
+                }));
+}

