+using Microsoft.Extensions.Options;
+using WorkItems.Api.Notifications;
+using Xunit;
+
+namespace WorkItems.Api.Tests;
+
+public sealed class NotificationProviderContractTests
+{
+    private const string FailureTitleMarker = "[notify-fail]";
+
+    [Fact]
+    public async Task DemoProvider_RegularAndEscalationNotificationsReturnSuccess()
+    {
+        var cancellationToken = TestContext.Current.CancellationToken;
+        var provider = CreateProvider();
+        var notification = new OverdueNotification(Guid.NewGuid(), "通知成功");
+
+        var overdueSucceeded = await provider.SendOverdueAsync(
+            notification,
+            cancellationToken);
+        var escalationSucceeded = await provider.SendEscalationAsync(
+            notification,
+            cancellationToken);
+
+        Assert.True(overdueSucceeded);
+        Assert.True(escalationSucceeded);
+    }
+
+    [Fact]
+    public async Task DemoProvider_FailureMarkerReturnsFalseForBothNotificationKinds()
+    {
+        var cancellationToken = TestContext.Current.CancellationToken;
+        var provider = CreateProvider();
+        var notification = new OverdueNotification(
+            Guid.NewGuid(),
+            $"通知失敗 {FailureTitleMarker.ToUpperInvariant()}");
+
+        var overdueSucceeded = await provider.SendOverdueAsync(
+            notification,
+            cancellationToken);
+        var escalationSucceeded = await provider.SendEscalationAsync(
+            notification,
+            cancellationToken);
+
+        Assert.False(overdueSucceeded);
+        Assert.False(escalationSucceeded);
+    }
+
+    [Fact]
+    public async Task DemoProvider_CanceledTokenStopsBothNotificationKinds()
+    {
+        var provider = CreateProvider();
+        var notification = new OverdueNotification(Guid.NewGuid(), "取消通知");
+        using var cancellationSource = new CancellationTokenSource();
+        await cancellationSource.CancelAsync();
+
+        var overdueException = await Assert.ThrowsAsync<OperationCanceledException>(
+            () => provider.SendOverdueAsync(notification, cancellationSource.Token));
+        var escalationException = await Assert.ThrowsAsync<OperationCanceledException>(
+            () => provider.SendEscalationAsync(notification, cancellationSource.Token));
+
+        Assert.Equal(cancellationSource.Token, overdueException.CancellationToken);
+        Assert.Equal(cancellationSource.Token, escalationException.CancellationToken);
+    }
+
+    private static IOverdueNotificationProvider CreateProvider() =>
+        new DemoNotificationProvider(
+            Options.Create(
+                new DemoNotificationOptions
+                {
+                    FailureTitleMarker = FailureTitleMarker
+                }));
+}

