+namespace WorkItems.Api.Contracts;
+
+/// <summary>
+/// 提供通知端傳送逾期工作項目通知所需的資料。
+/// </summary>
+/// <param name="WorkItemId">工作項目識別碼。</param>
+/// <param name="Title">工作項目標題。</param>
+public sealed record OverdueWorkItemNotification(Guid WorkItemId, string Title);
+
+/// <summary>
+/// 定義逾期工作項目通知供應端必須提供的操作。
+/// </summary>
+public interface INotificationProvider
+{
+    /// <summary>
+    /// 傳送工作項目逾期通知。
+    /// </summary>
+    /// <param name="notification">通知端所需的工作項目資料。</param>
+    /// <param name="cancellationToken">取消權杖。</param>
+    /// <returns>通知成功時為 <see langword="true"/>；失敗時為 <see langword="false"/>。</returns>
+    Task<bool> SendOverdueAsync(
+        OverdueWorkItemNotification notification,
+        CancellationToken cancellationToken);
+
+    /// <summary>
+    /// 傳送工作項目的逾期升級通知。
+    /// </summary>
+    /// <param name="notification">通知端所需的工作項目資料。</param>
+    /// <param name="cancellationToken">取消權杖。</param>
+    /// <returns>通知成功時為 <see langword="true"/>；失敗時為 <see langword="false"/>。</returns>
+    Task<bool> SendEscalationAsync(
+        OverdueWorkItemNotification notification,
+        CancellationToken cancellationToken);
+}
