+using Microsoft.Extensions.Options;
+using WorkItems.Api.Contracts;
+using WorkItems.Api.Notifications;
+using Xunit;
+
+namespace WorkItems.Api.Tests;
+
+public sealed class NotificationProviderContractTests
+{
+    private const string FailureTitleMarker = "[notify-fail]";
+
+    [Theory]
+    [InlineData(false)]
+    [InlineData(true)]
+    public async Task DemoProvider_WhenNotificationHasNoFailureMarker_ReturnsSuccess(
+        bool useEscalationNotification)
+    {
+        var cancellationToken = TestContext.Current.CancellationToken;
+        var provider = CreateProvider();
+        var notification = new OverdueWorkItemNotification(Guid.NewGuid(), "逾期通知成功");
+
+        var succeeded = await SendAsync(
+            provider,
+            notification,
+            useEscalationNotification,
+            cancellationToken);
+
+        Assert.True(succeeded);
+    }
+
+    [Theory]
+    [InlineData(false)]
+    [InlineData(true)]
+    public async Task DemoProvider_WhenNotificationHasFailureMarker_ReturnsFailure(
+        bool useEscalationNotification)
+    {
+        var cancellationToken = TestContext.Current.CancellationToken;
+        var provider = CreateProvider();
+        var notification = new OverdueWorkItemNotification(
+            Guid.NewGuid(),
+            $"逾期通知{FailureTitleMarker}");
+
+        var succeeded = await SendAsync(
+            provider,
+            notification,
+            useEscalationNotification,
+            cancellationToken);
+
+        Assert.False(succeeded);
+    }
+
+    [Theory]
+    [InlineData(false)]
+    [InlineData(true)]
+    public async Task DemoProvider_WhenCanceled_PropagatesCancellation(
+        bool useEscalationNotification)
+    {
+        using var cancellation = new CancellationTokenSource();
+        await cancellation.CancelAsync();
+        var provider = CreateProvider();
+        var notification = new OverdueWorkItemNotification(Guid.NewGuid(), "取消通知");
+
+        var exception = await Assert.ThrowsAsync<OperationCanceledException>(
+            () => SendAsync(
+                provider,
+                notification,
+                useEscalationNotification,
+                cancellation.Token));
+
+        Assert.Equal(cancellation.Token, exception.CancellationToken);
+    }
+
+    private static DemoNotificationProvider CreateProvider() =>
+        new(Options.Create(new DemoNotificationOptions
+        {
+            FailureTitleMarker = FailureTitleMarker
+        }));
+
+    private static Task<bool> SendAsync(
+        INotificationProvider provider,
+        OverdueWorkItemNotification notification,
+        bool useEscalationNotification,
+        CancellationToken cancellationToken) =>
+        useEscalationNotification
+            ? provider.SendEscalationAsync(notification, cancellationToken)
+            : provider.SendOverdueAsync(notification, cancellationToken);
+}

