+using Microsoft.Extensions.Options;
+using WorkItems.Api.Notifications;
+using Xunit;
+
+namespace WorkItems.Api.Tests;
+
+/// <summary>
+/// 驗證通知 Provider 對 Use Case 承諾的成功、失敗與取消契約。
+/// </summary>
+public sealed class NotificationProviderContractTests
+{
+    private const string FailureTitleMarker = "[provider-failure]";
+
+    [Fact]
+    public async Task SendOverdueAsync_WhenTitleDoesNotContainFailureMarker_ReturnsTrue()
+    {
+        var provider = CreateProvider();
+        var notification = CreateNotification("一般逾期通知");
+
+        var succeeded = await provider.SendOverdueAsync(
+            notification,
+            TestContext.Current.CancellationToken);
+
+        Assert.True(succeeded);
+    }
+
+    [Fact]
+    public async Task SendOverdueAsync_WhenTitleContainsFailureMarker_ReturnsFalse()
+    {
+        var provider = CreateProvider();
+        var notification = CreateNotification($"通知 {FailureTitleMarker.ToUpperInvariant()}");
+
+        var succeeded = await provider.SendOverdueAsync(
+            notification,
+            TestContext.Current.CancellationToken);
+
+        Assert.False(succeeded);
+    }
+
+    [Fact]
+    public async Task SendEscalationAsync_WhenTitleContainsFailureMarker_ReturnsFalse()
+    {
+        var provider = CreateProvider();
+        var notification = CreateNotification($"升級通知 {FailureTitleMarker}");
+
+        var succeeded = await provider.SendEscalationAsync(
+            notification,
+            TestContext.Current.CancellationToken);
+
+        Assert.False(succeeded);
+    }
+
+    [Fact]
+    public async Task SendOverdueAsync_WhenCancellationIsRequested_ThrowsOperationCanceledException()
+    {
+        var provider = CreateProvider();
+        using var cancellationSource = new CancellationTokenSource();
+        await cancellationSource.CancelAsync();
+
+        await Assert.ThrowsAnyAsync<OperationCanceledException>(
+            () => provider.SendOverdueAsync(
+                CreateNotification("已取消的一般通知"),
+                cancellationSource.Token));
+    }
+
+    [Fact]
+    public async Task SendEscalationAsync_WhenCancellationIsRequested_ThrowsOperationCanceledException()
+    {
+        var provider = CreateProvider();
+        using var cancellationSource = new CancellationTokenSource();
+        await cancellationSource.CancelAsync();
+
+        await Assert.ThrowsAnyAsync<OperationCanceledException>(
+            () => provider.SendEscalationAsync(
+                CreateNotification("已取消的升級通知"),
+                cancellationSource.Token));
+    }
+
+    private static INotificationProvider CreateProvider() =>
+        new DemoNotificationProvider(
+            Options.Create(
+                new DemoNotificationOptions
+                {
+                    FailureTitleMarker = FailureTitleMarker
+                }));
+
+    private static WorkItemNotification CreateNotification(string title) =>
+        new(Guid.NewGuid(), title);
+}

