+using Microsoft.Extensions.Options;
+
+namespace WorkItems.Api.Notifications;
+
+/// <summary>
+/// Demo 通知供應商的設定。
+/// </summary>
+public sealed class DemoNotificationOptions
+{
+    /// <summary>
+    /// 取得設定區段名稱。
+    /// </summary>
+    public const string SectionName = "DemoNotification";
+
+    /// <summary>
+    /// 取得會讓 Demo 通知回報失敗的標題文字。
+    /// </summary>
+    public string FailureTitleMarker { get; init; } = "[notify-fail]";
+}
+
+/// <summary>
+/// 表示逾期通知 Provider 傳送通知所需的工作項目資料。
+/// </summary>
+/// <param name="WorkItemId">工作項目識別碼。</param>
+/// <param name="Title">工作項目標題。</param>
+public sealed record OverdueNotification(Guid WorkItemId, string Title);
+
+/// <summary>
+/// 定義逾期通知 Provider 必須提供的傳送能力。
+/// </summary>
+public interface IOverdueNotificationProvider
+{
+    /// <summary>
+    /// 傳送工作項目逾期通知。
+    /// </summary>
+    /// <param name="notification">要傳送的逾期通知資料。</param>
+    /// <param name="cancellationToken">取消權杖。</param>
+    /// <returns>通知成功時為 <see langword="true"/>；失敗時為 <see langword="false"/>。</returns>
+    Task<bool> SendOverdueAsync(
+        OverdueNotification notification,
+        CancellationToken cancellationToken);
+
+    /// <summary>
+    /// 傳送高優先序工作項目的逾期升級通知。
+    /// </summary>
+    /// <param name="notification">要傳送的逾期通知資料。</param>
+    /// <param name="cancellationToken">取消權杖。</param>
+    /// <returns>通知成功時為 <see langword="true"/>；失敗時為 <see langword="false"/>。</returns>
+    Task<bool> SendEscalationAsync(
+        OverdueNotification notification,
+        CancellationToken cancellationToken);
+}
+
+/// <summary>
+/// 提供本機範例的決定性通知 Provider。
+/// </summary>
+public sealed class DemoNotificationProvider(IOptions<DemoNotificationOptions> options)
+    : IOverdueNotificationProvider
+{
+    private readonly DemoNotificationOptions notificationOptions = options.Value;
+
+    /// <inheritdoc />
+    public Task<bool> SendOverdueAsync(
+        OverdueNotification notification,
+        CancellationToken cancellationToken)
+    {
+        cancellationToken.ThrowIfCancellationRequested();
+
+        var succeeded = !notification.Title.Contains(
+            notificationOptions.FailureTitleMarker,
+            StringComparison.OrdinalIgnoreCase);
+        return Task.FromResult(succeeded);
+    }
+
+    /// <inheritdoc />
+    public Task<bool> SendEscalationAsync(
+        OverdueNotification notification,
+        CancellationToken cancellationToken) =>
+        SendOverdueAsync(notification, cancellationToken);
+}
