+
+namespace WorkItems.Api.Tests;
+
+/// <summary>
+/// 固定所有逾期通知 Provider 都必須維持的 Consumer 契約。
+/// </summary>
+public abstract class NotificationProviderContractTests
+{
+    private const string FailureTitleMarker = "[契約測試通知失敗]";
+
+    /// <summary>
+    /// 建立要接受共同契約驗證的通知 Provider。
+    /// </summary>
+    /// <returns>待驗證的通知 Provider。</returns>
+    protected abstract IOverdueNotificationProvider CreateProvider();
+
+    [Theory]
+    [InlineData(false)]
+    [InlineData(true)]
+    public async Task SendAsync_WhenProviderAcceptsNotification_ReturnsTrue(bool escalation)
+    {
+        var cancellationToken = TestContext.Current.CancellationToken;
+        var provider = CreateProvider();
+        var notification = new OverdueNotification(Guid.NewGuid(), "契約測試通知成功");
+
+        var succeeded = await SendAsync(
+            provider,
+            notification,
+            escalation,
+            cancellationToken);
+
+        Assert.True(succeeded);
+    }
+
+    [Theory]
+    [InlineData(false)]
+    [InlineData(true)]
+    public async Task SendAsync_WhenProviderRejectsNotification_ReturnsFalse(bool escalation)
+    {
+        var cancellationToken = TestContext.Current.CancellationToken;
+        var provider = CreateProvider();
+        var notification = new OverdueNotification(
+            Guid.NewGuid(),
+            $"{FailureTitleMarker}契約測試");
+
+        var succeeded = await SendAsync(
+            provider,
+            notification,
+            escalation,
+            cancellationToken);
+
+        Assert.False(succeeded);
+    }
+
+    [Theory]
+    [InlineData(false)]
+    [InlineData(true)]
+    public async Task SendAsync_WhenCancellationRequested_ThrowsCancellation(bool escalation)
+    {
+        var provider = CreateProvider();
+        var notification = new OverdueNotification(Guid.NewGuid(), "契約測試取消");
+        using var cancellationSource = new CancellationTokenSource();
+        await cancellationSource.CancelAsync();
+
+        await Assert.ThrowsAnyAsync<OperationCanceledException>(
+            () => SendAsync(
+                provider,
+                notification,
+                escalation,
+                cancellationSource.Token));
+    }
+
+    private static Task<bool> SendAsync(
+        IOverdueNotificationProvider provider,
+        OverdueNotification notification,
+        bool escalation,
+        CancellationToken cancellationToken) =>
+        escalation
+            ? provider.SendEscalationAsync(notification, cancellationToken)
+            : provider.SendOverdueAsync(notification, cancellationToken);
+
+    /// <summary>
+    /// 建立共同契約測試使用的 Demo 通知設定。
+    /// </summary>
+    protected static DemoNotificationOptions CreateOptions() =>
+        new()
+        {
+            FailureTitleMarker = FailureTitleMarker
+        };
+}
+
+/// <summary>
+/// 驗證 Demo 通知 Provider 符合逾期通知 Consumer 契約。
+/// </summary>
+public sealed class DemoNotificationProviderContractTests : NotificationProviderContractTests
+{
+    /// <inheritdoc />
+    protected override IOverdueNotificationProvider CreateProvider() =>
+        new DemoNotificationProvider(Options.Create(CreateOptions()));
+}

