+namespace WorkItems.Api.Notifications;
+
+/// <summary>
+/// 定義逾期通知的種類。
+/// </summary>
+public enum OverdueNotificationKind
+{
+    /// <summary>
+    /// 一般逾期通知。
+    /// </summary>
+    Overdue,
+
+    /// <summary>
+    /// 逾期升級通知。
+    /// </summary>
+    Escalation
+}
+
+/// <summary>
+/// 表示通知 Provider 傳送逾期通知所需的資料。
+/// </summary>
+/// <param name="WorkItemId">工作項目識別碼。</param>
+/// <param name="Title">工作項目標題。</param>
+/// <param name="Kind">通知種類。</param>
+public sealed record OverdueNotification(
+    Guid WorkItemId,
+    string Title,
+    OverdueNotificationKind Kind);
+
+/// <summary>
+/// 定義可替換的逾期通知 Provider 契約。
+/// </summary>
+public interface IOverdueNotificationProvider
+{
+    /// <summary>
+    /// 傳送逾期通知。
+    /// </summary>
+    /// <param name="notification">通知所需資料。</param>
+    /// <param name="cancellationToken">取消權杖。</param>
+    /// <returns>通知成功時為 <see langword="true" />；失敗時為 <see langword="false" />。</returns>
+    Task<bool> SendAsync(
+        OverdueNotification notification,
+        CancellationToken cancellationToken);
+}
