+using Microsoft.Extensions.Options;
+using WorkItems.Api.Models;
+using WorkItems.Api.Notifications;
+using Xunit;
+
+namespace WorkItems.Api.Tests;
+
+public sealed class NotificationProviderContractTests
+{
+    [Theory]
+    [InlineData(OverdueNotificationKind.Overdue)]
+    [InlineData(OverdueNotificationKind.Escalation)]
+    public async Task DemoProvider_PreservesSuccessAndFailureResultSemantics(
+        OverdueNotificationKind kind)
+    {
+        var cancellationToken = TestContext.Current.CancellationToken;
+        var provider = CreateDemoProvider();
+
+        var succeeded = await provider.SendAsync(
+            new OverdueNotification(Guid.NewGuid(), "通知成功", kind),
+            cancellationToken);
+        var failed = await provider.SendAsync(
+            new OverdueNotification(Guid.NewGuid(), "工作項目 [notify-fail]", kind),
+            cancellationToken);
+        var failedIgnoringCase = await provider.SendAsync(
+            new OverdueNotification(Guid.NewGuid(), "工作項目 [NOTIFY-FAIL]", kind),
+            cancellationToken);
+
+        Assert.True(succeeded);
+        Assert.False(failed);
+        Assert.False(failedIgnoringCase);
+    }
+
+    [Theory]
+    [InlineData(OverdueNotificationKind.Overdue)]
+    [InlineData(OverdueNotificationKind.Escalation)]
+    public async Task DemoProvider_WhenCanceled_ThrowsWithTheConsumerToken(
+        OverdueNotificationKind kind)
+    {
+        using var cancellation = new CancellationTokenSource();
+        await cancellation.CancelAsync();
+        var provider = CreateDemoProvider();
+
+        var exception = await Assert.ThrowsAsync<OperationCanceledException>(
+            () => provider.SendAsync(
+                new OverdueNotification(Guid.NewGuid(), "取消通知", kind),
+                cancellation.Token));
+
+        Assert.Equal(cancellation.Token, exception.CancellationToken);
+    }
+
+    [Theory]
+    [InlineData(OverdueNotificationKind.Overdue, false)]
+    [InlineData(OverdueNotificationKind.Escalation, true)]
+    public async Task Gateway_MapsTheConsumerContractAndPreservesProviderFailure(
+        OverdueNotificationKind expectedKind,
+        bool sendEscalation)
+    {
+        var cancellationToken = TestContext.Current.CancellationToken;
+        var provider = new RecordingProvider(deliverySucceeded: false);
+        var gateway = new DemoNotificationGateway(provider);
+        var workItem = new WorkItem
+        {
+            Id = Guid.NewGuid(),
+            Title = "保留 Consumer 契約",
+            Priority = "Normal",
+            DueAtUtc = DateTimeOffset.Parse("2026-09-01T00:00:00Z"),
+            CreatedAtUtc = DateTimeOffset.Parse("2026-08-31T00:00:00Z")
+        };
+
+        var succeeded = sendEscalation
+            ? await gateway.SendEscalationAsync(workItem, cancellationToken)
+            : await gateway.SendOverdueAsync(workItem, cancellationToken);
+
+        Assert.False(succeeded);
+        var notification = Assert.Single(provider.Notifications);
+        Assert.Equal(workItem.Id, notification.WorkItemId);
+        Assert.Equal(workItem.Title, notification.Title);
+        Assert.Equal(expectedKind, notification.Kind);
+        Assert.Equal(cancellationToken, provider.CancellationToken);
+    }
+
+    [Fact]
+    public async Task Gateway_WhenProviderThrows_PropagatesTheSameFailure()
+    {
+        var expectedException = new InvalidOperationException("通知供應端無法使用。");
+        var provider = new RecordingProvider(exception: expectedException);
+        var gateway = new DemoNotificationGateway(provider);
+        var workItem = new WorkItem
+        {
+            Id = Guid.NewGuid(),
+            Title = "通知例外",
+            Priority = "Normal",
+            DueAtUtc = DateTimeOffset.Parse("2026-09-01T00:00:00Z"),
+            CreatedAtUtc = DateTimeOffset.Parse("2026-08-31T00:00:00Z")
+        };
+
+        var actualException = await Assert.ThrowsAsync<InvalidOperationException>(
+            () => gateway.SendOverdueAsync(
+                workItem,
+                TestContext.Current.CancellationToken));
+
+        Assert.Same(expectedException, actualException);
+    }
+
+    private static DemoNotificationProvider CreateDemoProvider() =>
+        new(Options.Create(new DemoNotificationOptions()));
+
+    private sealed class RecordingProvider(
+        bool deliverySucceeded = true,
+        Exception? exception = null) : IOverdueNotificationProvider
+    {
+        private readonly List<OverdueNotification> notifications = [];
+
+        public IReadOnlyList<OverdueNotification> Notifications => notifications;
+
+        public CancellationToken CancellationToken { get; private set; }
+
+        public Task<bool> SendAsync(
+            OverdueNotification notification,
+            CancellationToken cancellationToken)
+        {
+            notifications.Add(notification);
+            CancellationToken = cancellationToken;
+
+            return exception is null
+                ? Task.FromResult(deliverySucceeded)
+                : Task.FromException<bool>(exception);
+        }
+    }
+}
